import { utilityProcess, type UtilityProcess } from "electron";
import { createWriteStream } from "node:fs";
import path from "node:path";
import { log, logsDir } from "./paths";

const HOST_VARS = ["PATH", "Path", "PATHEXT", "SystemRoot", "SYSTEMROOT", "windir", "TEMP", "TMP", "TMPDIR", "HOME", "USERPROFILE", "APPDATA", "LOCALAPPDATA", "ProgramData", "LANG", "LC_ALL", "TZ"];

export type NextServerOptions = { appDir: string; port: number; env: Record<string, string> };

const READY_TIMEOUT = 90_000;

export class NextServer {
  private child?: UtilityProcess;
  private stopping = false;
  private restarts = 0;
  private restartTimer?: NodeJS.Timeout;
  private output = createWriteStream(path.join(logsDir(), "next.log"), { flags: "a" });
  private recent: string[] = [];

  constructor(private options: NextServerOptions, private onDown: (error: Error) => void) {}

  get url() { return `http://localhost:${this.options.port}`; }
  get pid() { return this.child?.pid; }

  async start() {
    this.stopping = false;
    const startedAt = Date.now();
    const child = this.spawn();
    await this.waitReady(child);
    child.once("exit", code => {
      if (this.stopping || this.child !== child) return;
      log(`Next server exited with ${code}`);
      if (Date.now() - startedAt > 60_000) this.restarts = 0;
      this.scheduleRestart();
    });
  }

  private spawn() {
    const host = Object.fromEntries(HOST_VARS.flatMap(name => process.env[name] ? [[name, process.env[name]!]] : []));
    const env = {
      ...host,
      ...this.options.env,
      PORT: String(this.options.port),
      HOSTNAME: "127.0.0.1",
      NEXT_PUBLIC_APP_URL: `http://localhost:${this.options.port}`,
      MONEO_DESKTOP: "1",
      ...(process.env.MONEO_DESKTOP_PREVIEW === "1" ? { MONEO_DESKTOP_PREVIEW: "1" } : {}),
      NODE_ENV: "production",
      NEXT_TELEMETRY_DISABLED: "1",
    };
    const child = utilityProcess.fork(path.join(this.options.appDir, "server.js"), [], {
      cwd: this.options.appDir, env, stdio: "pipe", serviceName: "Moneo server",
    });
    const record = (chunk: Buffer) => {
      this.output.write(chunk);
      this.recent.push(...chunk.toString().split(/\r?\n/).filter(Boolean));
      this.recent.splice(0, Math.max(0, this.recent.length - 20));
    };
    child.stdout?.on("data", record);
    child.stderr?.on("data", record);
    child.once("spawn", () => log(`Next server process ${child.pid}`));
    this.child = child;
    log(`Next server starting on port ${this.options.port}`);
    return child;
  }

  private async waitReady(child: UtilityProcess) {
    let exited: number | null | undefined;
    child.once("exit", code => { exited = code; });
    const deadline = Date.now() + READY_TIMEOUT;
    while (Date.now() < deadline) {
      if (exited !== undefined) throw new Error(`The Moneo server stopped while starting (exit ${exited}).\n${this.recent.slice(-8).join("\n")}`);
      try {
        const response = await fetch(`http://127.0.0.1:${this.options.port}/api/health`, { headers: { authorization: "Bearer readiness" }, signal: AbortSignal.timeout(5_000) });
        if (response.status < 500) { log("Next server is ready"); return; }
      } catch {}
      await new Promise(resolve => setTimeout(resolve, 250));
    }
    child.kill();
    throw new Error(`The Moneo server did not answer within ${READY_TIMEOUT / 1000} seconds.\n${this.recent.slice(-8).join("\n")}`);
  }

  private scheduleRestart() {
    const delay = Math.min(30_000, 1_000 * 2 ** this.restarts++);
    log(`Restarting the Next server in ${delay} ms`);
    this.restartTimer = setTimeout(() => {
      this.start().catch(error => {
        log(`Next server restart failed: ${error instanceof Error ? error.message : error}`);
        if (this.restarts >= 6) this.onDown(error instanceof Error ? error : new Error(String(error)));
        else this.scheduleRestart();
      });
    }, delay);
  }

  async stop() {
    this.stopping = true;
    clearTimeout(this.restartTimer);
    const child = this.child;
    this.child = undefined;
    if (!child?.pid) return;
    await new Promise<void>(resolve => {
      const force = setTimeout(resolve, 10_000);
      child.once("exit", () => { clearTimeout(force); resolve(); });
      child.kill();
    });
    log("Next server stopped");
  }
}
import { spawn, fork as nodeFork, type ChildProcess } from "node:child_process";
import { createWriteStream, existsSync, realpathSync, type WriteStream } from "node:fs";
import fs from "node:fs/promises";
import net from "node:net";
import path from "node:path";

export interface ForkedProcess {
  readonly pid?: number;
  readonly stdout: NodeJS.ReadableStream | null;
  readonly stderr: NodeJS.ReadableStream | null;
  kill(): boolean;
  once(event: "exit", listener: (code: number | null) => void): unknown;
}
export type ForkFn = (modulePath: string, args: string[], options: { env: Record<string, string>; cwd: string; serviceName: string }) => ForkedProcess;

export const defaultFork: ForkFn = (modulePath, args, options) => {
  if (process.versions.electron) {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const { utilityProcess } = require("electron") as typeof import("electron");
    return utilityProcess.fork(modulePath, args, { env: options.env, cwd: options.cwd, stdio: "pipe", serviceName: options.serviceName }) as unknown as ForkedProcess;
  }
  return nodeFork(modulePath, args, { env: options.env, cwd: options.cwd, stdio: ["ignore", "pipe", "pipe", "ipc"], windowsHide: true }) as ForkedProcess;
};

export const exe = process.platform === "win32" ? ".exe" : "";

export function platformKey() {
  const keys: Record<string, string> = { "win32-x64": "win-x64", "darwin-arm64": "mac-arm64", "darwin-x64": "mac-x64", "linux-x64": "linux-x64" };
  const key = keys[`${process.platform}-${process.arch}`];
  if (!key) throw new Error(`Moneo Desktop has no native backend for ${process.platform}-${process.arch}`);
  return key;
}

export async function openLog(logs: string, name: string): Promise<WriteStream> {
  await fs.mkdir(logs, { recursive: true });
  const file = path.join(logs, `${name}.log`);
  const stat = await fs.stat(file).catch(() => undefined);
  if (stat && stat.size > 10 * 1024 * 1024) await fs.rename(file, `${file}.1`);
  return createWriteStream(file, { flags: "a" });
}

export function pipeTo(log: WriteStream, child: { stdout: NodeJS.ReadableStream | null; stderr: NodeJS.ReadableStream | null }) {
  child.stdout?.pipe(log, { end: false });
  child.stderr?.pipe(log, { end: false });
}

export function runProgram(file: string, args: string[], options: { env?: NodeJS.ProcessEnv; cwd?: string; timeoutMs?: number; log?: WriteStream; waitForClose?: boolean } = {}) {
  return new Promise<{ code: number | null; output: string }>((resolve, reject) => {
    const child = spawn(file, args, { env: options.env ?? process.env, cwd: options.cwd, stdio: ["ignore", "pipe", "pipe"], windowsHide: true });
    let output = "";
    const collect = (chunk: Buffer) => { output += chunk.toString(); options.log?.write(chunk); };
    child.stdout.on("data", collect);
    child.stderr.on("data", collect);
    const timer = options.timeoutMs ? setTimeout(() => { child.kill(); reject(new Error(`${path.basename(file)} timed out after ${options.timeoutMs} ms\n${output}`)); }, options.timeoutMs) : undefined;
    child.once("error", error => { clearTimeout(timer); reject(error); });
    child.once(options.waitForClose ? "close" : "exit", code => { clearTimeout(timer); resolve({ code, output }); });
  });
}

export async function mustRun(file: string, args: string[], options: Parameters<typeof runProgram>[2] = {}) {
  const result = await runProgram(file, args, options);
  if (result.code !== 0) throw new Error(`${path.basename(file)} ${args[0] ?? ""} failed (exit ${result.code}):\n${result.output.trim()}`);
  return result.output;
}

export function spawnService(file: string, args: string[], env: NodeJS.ProcessEnv, cwd: string): ChildProcess {
  return spawn(file, args, { env, cwd, stdio: ["ignore", "pipe", "pipe"], windowsHide: true });
}

export function portIsFree(port: number) {
  return new Promise<boolean>(resolve => {
    const server = net.createServer();
    server.once("error", () => resolve(false));
    server.listen({ host: "127.0.0.1", port, exclusive: true }, () => server.close(() => resolve(true)));
  });
}

export function freePort() {
  return new Promise<number>((resolve, reject) => {
    const server = net.createServer();
    server.once("error", reject);
    server.listen({ host: "127.0.0.1", port: 0, exclusive: true }, () => {
      const { port } = server.address() as net.AddressInfo;
      server.close(() => resolve(port));
    });
  });
}

export async function preferredPort(port: number) {
  return (await portIsFree(port)) ? port : freePort();
}

export async function waitFor(what: string, check: () => Promise<boolean>, timeoutMs: number, exited?: () => string | undefined) {
  const deadline = Date.now() + timeoutMs;
  let last: unknown;
  for (;;) {
    const gone = exited?.();
    if (gone) throw new Error(`${what} stopped while starting: ${gone}`);
    try { if (await check()) return; } catch (error) { last = error; }
    if (Date.now() > deadline) throw new Error(`${what} did not become ready within ${timeoutMs / 1000} s${last ? ` (${(last as Error).message})` : ""}`);
    await new Promise(resolve => setTimeout(resolve, 250));
  }
}

export async function httpOk(url: string) {
  const response = await fetch(url, { signal: AbortSignal.timeout(2000) });
  await response.body?.cancel();
  return response.ok;
}

export function isAlive(pid: number) {
  try { process.kill(pid, 0); return true; } catch (error) { return (error as NodeJS.ErrnoException).code === "EPERM"; }
}

export type ProcessInfo = { exe?: string; commandLine?: string };

export async function processInfo(pids: number[]): Promise<Map<number, ProcessInfo>> {
  const result = new Map<number, ProcessInfo>();
  const alive = [...new Set(pids)].filter(pid => Number.isInteger(pid) && pid > 0 && isAlive(pid));
  if (!alive.length) return result;
  if (process.platform === "win32") {
    const filter = alive.map(pid => `ProcessId=${pid}`).join(" OR ");
    const { output } = await runProgram("powershell.exe", ["-NoProfile", "-NonInteractive", "-Command",
      `Get-CimInstance Win32_Process -Filter '${filter}' | Select-Object ProcessId,ExecutablePath,CommandLine | ConvertTo-Json -Compress`], { timeoutMs: 30_000 });
    const parsed = output.trim() ? JSON.parse(output) : [];
    for (const row of Array.isArray(parsed) ? parsed : [parsed])
      result.set(row.ProcessId, { exe: row.ExecutablePath ?? undefined, commandLine: row.CommandLine ?? undefined });
    return result;
  }
  for (const pid of alive) {
    if (process.platform === "linux") {
      const exe = await fs.readlink(`/proc/${pid}/exe`).catch(() => undefined);
      const commandLine = await fs.readFile(`/proc/${pid}/cmdline`, "utf8").then(text => text.split(String.fromCharCode(0)).join(" ")).catch(() => undefined);
      result.set(pid, { exe, commandLine });
    } else {
      const exe = (await runProgram("ps", ["-p", String(pid), "-o", "comm="])).output.trim() || undefined;
      const commandLine = (await runProgram("ps", ["-p", String(pid), "-o", "args="])).output.trim() || undefined;
      result.set(pid, { exe, commandLine });
    }
  }
  return result;
}

const comparable = (file: string) => {
  let resolved = path.resolve(file);
  try { resolved = realpathSync.native(resolved); } catch {}
  return process.platform === "win32" ? resolved.toLowerCase() : resolved;
};

export function isInside(file: string | undefined, dir: string) {
  if (!file) return false;
  const relative = path.relative(comparable(dir), comparable(file));
  return relative === "" || (!relative.startsWith("..") && !path.isAbsolute(relative));
}

export const mentions = (commandLine: string | undefined, file: string) => {
  const normalize = (text: string) => (process.platform === "win32" ? text.toLowerCase() : text).replaceAll("\\", "/");
  return commandLine !== undefined && normalize(commandLine).includes(normalize(path.resolve(file)));
};

export const samePath = (a: string | undefined, b: string) => a !== undefined && comparable(a) === comparable(b);

async function terminate(pid: number) {
  try { process.kill(pid); } catch { return; }
  const deadline = Date.now() + 5000;
  while (isAlive(pid) && Date.now() < deadline) await new Promise(resolve => setTimeout(resolve, 100));
  if (isAlive(pid)) try { process.kill(pid, "SIGKILL"); } catch {}
}

export type PidEntry = { service: string; pid: number; exe: string; script?: string };

export class PidFile {
  constructor(private file: string) {}
  async read(): Promise<PidEntry[]> {
    if (!existsSync(this.file)) return [];
    try { return (JSON.parse(await fs.readFile(this.file, "utf8")) as PidEntry[]).filter(entry => entry.exe && entry.pid); } catch { return []; }
  }
  async write(entries: PidEntry[]) {
    await fs.mkdir(path.dirname(this.file), { recursive: true });
    await fs.writeFile(this.file, JSON.stringify(entries));
  }
  async killStale(bundle: string[], log: (line: string) => void) {
    const bundled = (file: string | undefined) => bundle.some(dir => isInside(file, dir));
    const entries = await this.read();
    const info = await processInfo(entries.map(entry => entry.pid));
    for (const entry of entries) {
      const found = info.get(entry.pid);
      if (!found) continue;
      const ours = samePath(found.exe, entry.exe) && (entry.script
        ? bundled(entry.script) && mentions(found.commandLine, entry.script)
        : bundled(found.exe));
      if (!ours) { log(`Leaving pid ${entry.pid} alone: it is no longer ${entry.service} (${found.exe ?? "unknown executable"})`); continue; }
      log(`Stopping ${entry.service} (pid ${entry.pid}) left running by an earlier session`);
      await terminate(entry.pid);
    }
    await fs.rm(this.file, { force: true });
  }
}
import { existsSync } from "node:fs";
import fs from "node:fs/promises";
import path from "node:path";
import { exe, isAlive, isInside, mentions, mustRun, processInfo, runProgram } from "./processes";

export type Cluster = { bin: string; data: string; logs: string; port: number; password: string };

const program = (cluster: Pick<Cluster, "bin">, name: string) => path.join(cluster.bin, `${name}${exe}`);

export const isInitialized = (data: string) => existsSync(path.join(data, "PG_VERSION"));

export async function bundledMajor(bin: string) {
  const output = await mustRun(program({ bin }, "postgres"), ["--version"], { waitForClose: true });
  const major = output.match(/PostgreSQL\)\s+(\d+)/)?.[1];
  if (!major) throw new Error(`Could not read the bundled PostgreSQL version from "${output.trim()}"`);
  return major;
}

export async function checkMajor(cluster: Cluster) {
  const data = (await fs.readFile(path.join(cluster.data, "PG_VERSION"), "utf8")).trim();
  const bundled = await bundledMajor(cluster.bin);
  if (data !== bundled) throw new Error(`The database was created by PostgreSQL ${data}, but this Moneo bundles PostgreSQL ${bundled}. Install the matching Moneo version or restore a backup.`);
}

export async function initCluster(cluster: Cluster, home: string) {
  await fs.mkdir(path.dirname(cluster.data), { recursive: true });
  const pwfile = path.join(home, `.initdb-${process.pid}`);
  await fs.writeFile(pwfile, cluster.password, { mode: 0o600 });
  try {
    const locales = process.platform === "win32" ? ["en-US"] : ["en_US.UTF-8", "C.UTF-8", "C"];
    let failure = "";
    for (const locale of locales) {
      await fs.rm(cluster.data, { recursive: true, force: true });
      const result = await runProgram(program(cluster, "initdb"), ["-D", cluster.data, "-U", "supabase_admin", `--pwfile=${pwfile}`,
        "--auth=scram-sha-256", "-E", "UTF8", "--locale-provider=icu", "--icu-locale=en-US", `--locale=${locale}`], { timeoutMs: 180_000 });
      if (result.code === 0) { failure = ""; break; }
      failure = result.output;
    }
    if (failure) throw new Error(`initdb failed:\n${failure.trim()}`);
  } finally {
    await fs.rm(pwfile, { force: true });
  }
  await fs.writeFile(path.join(cluster.data, "pg_hba.conf"),
    "# Moneo Desktop: password logins over TCP from this computer only; no Unix sockets.\n" +
    "# TYPE  DATABASE  USER  ADDRESS       METHOD\nhost    all       all   127.0.0.1/32  scram-sha-256\n");
  const conf = path.join(cluster.data, "postgresql.conf");
  await fs.appendFile(conf, "\n# Moneo Desktop settings, rewritten at every start.\ninclude 'moneo.conf'\n");
}

async function writeSettings(cluster: Cluster) {
  const logs = cluster.logs.replaceAll("\\", "/").replaceAll("'", "''");
  await fs.writeFile(path.join(cluster.data, "moneo.conf"), [
    "listen_addresses = '127.0.0.1'",
    `port = ${cluster.port}`,
    "unix_socket_directories = ''",
    "password_encryption = scram-sha-256",
    "timezone = 'UTC'",
    "log_timezone = 'UTC'",
    "datestyle = 'iso, mdy'",
    "row_security = on",
    "extra_float_digits = 0",
    "default_text_search_config = 'pg_catalog.english'",
    "jit = off",
    "logging_collector = on",
    `log_directory = '${logs}'`,
    "log_filename = 'postgres-%a.log'",
    "log_truncate_on_rotation = on",
    "log_rotation_age = 1d",
    "log_rotation_size = 0",
    "log_line_prefix = '%m [%p] %q%u@%d '",
    "",
  ].join("\n"));
}

async function postmasterPid(data: string) {
  const text = await fs.readFile(path.join(data, "postmaster.pid"), "utf8").catch(() => "");
  const pid = Number(text.split("\n")[0]);
  return Number.isInteger(pid) && pid > 0 ? pid : undefined;
}

export async function recoverStalePid(cluster: Cluster, log: (line: string) => void) {
  const pid = await postmasterPid(cluster.data);
  if (!pid) return;
  const found = (await processInfo([pid])).get(pid);
  const postgres = found?.exe !== undefined && path.basename(found.exe).toLowerCase() === `postgres${exe}`;
  if (postgres && (isInside(found.exe, cluster.bin) || mentions(found?.commandLine, cluster.data))) {
    log(`PostgreSQL (pid ${pid}) is still running from an earlier session; stopping it first`);
    await stopCluster(cluster);
  } else {
    log(`Removing stale postmaster.pid (pid ${pid} is ${found?.exe ? `now ${found.exe}` : "gone"})`);
    await fs.rm(path.join(cluster.data, "postmaster.pid"), { force: true });
  }
}

export async function startCluster(cluster: Cluster, log: (line: string) => void) {
  await fs.mkdir(cluster.logs, { recursive: true });
  await recoverStalePid(cluster, log);
  if (await postmasterPid(cluster.data)) throw new Error("PostgreSQL is still running from an earlier session and did not stop");
  await writeSettings(cluster);
  const { code, output } = await runProgram(program(cluster, "pg_ctl"),
    ["start", "-D", cluster.data, "-w", "-t", "120", "-l", path.join(cluster.logs, "postgres-start.log")], { timeoutMs: 150_000 });
  if (code !== 0) {
    const startLog = await fs.readFile(path.join(cluster.logs, "postgres-start.log"), "utf8").catch(() => "");
    throw new Error(`PostgreSQL did not start (pg_ctl exit ${code}):\n${output.trim()}\n${startLog.split("\n").slice(-15).join("\n")}`);
  }
  const pid = await postmasterPid(cluster.data);
  if (!pid) throw new Error("PostgreSQL started but wrote no postmaster.pid");
  return pid;
}

export async function stopCluster(cluster: Pick<Cluster, "bin" | "data">) {
  if (!(await postmasterPid(cluster.data))) return;
  const { code, output } = await runProgram(program(cluster, "pg_ctl"), ["stop", "-D", cluster.data, "-m", "fast", "-w", "-t", "60"], { timeoutMs: 90_000 });
  if (code !== 0 && !/does not exist|not running/i.test(output)) throw new Error(`pg_ctl stop failed (exit ${code}): ${output.trim()}`);
}

export async function runningPid(data: string) {
  const pid = await postmasterPid(data);
  return pid && isAlive(pid) ? pid : undefined;
}

