import { spawn, execFileSync } from "node:child_process";
import { existsSync, readFileSync, writeFileSync, rmSync, mkdtempSync } from "node:fs";
import os from "node:os";
import path from "node:path";

const root = process.argv[2];
const runs = Number(process.argv[3] ?? 3);
const out = process.argv[4];
const { chromium } = await import(path.join(root, "node_modules", "@playwright", "test", "index.mjs").replace(/\\/g, "/").replace(/^([A-Z]):/, "file:///$1:"));
const electron = path.join(root, "node_modules", "electron", "dist", "electron.exe");
const ps = command => execFileSync("powershell.exe", ["-NoProfile", "-Command", command], { encoding: "utf8", maxBuffer: 64 << 20 }).trim();
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
const freePort = () => new Promise(resolve => { import("node:net").then(({ createServer }) => { const s = createServer().listen(0, "127.0.0.1", () => { const { port } = s.address(); s.close(() => resolve(port)); }); }); });
async function until(what, test, timeout) {
  const deadline = Date.now() + timeout;
  for (;;) {
    const value = await test().catch(() => undefined);
    if (value) return value;
    if (Date.now() > deadline) throw new Error(`Timed out waiting for ${what}`);
    await sleep(25);
  }
}

function tree(mainPid, home) {
  const rows = JSON.parse(ps("Get-CimInstance Win32_Process | Select-Object ProcessId,ParentProcessId,Name,CommandLine,WorkingSetSize,PrivatePageCount | ConvertTo-Json -Compress"));
  const found = new Map(rows.filter(r => r.ProcessId === mainPid || (r.CommandLine ?? "").toLowerCase().includes(home.toLowerCase())).map(r => [r.ProcessId, r]));
  for (let grew = true; grew;) { grew = false; for (const r of rows) if (found.has(r.ParentProcessId) && !found.has(r.ProcessId)) { found.set(r.ProcessId, r); grew = true; } }
  return [...found.values()].map(r => ({ pid: r.ProcessId, name: r.Name, ws: r.WorkingSetSize, priv: Number(r.PrivatePageCount), cmd: (r.CommandLine ?? "").slice(0, 160) }));
}

function parseLog(file) {
  if (!existsSync(file)) return [];
  return readFileSync(file, "utf8").split(/\r?\n/).map(line => { const m = line.match(/^(\d{4}-\d\d-\d\dT[\d:.]+Z) (.*)$/); return m ? { at: Date.parse(m[1]), text: m[2] } : null; }).filter(Boolean);
}

async function startOnce(home, label) {
  const cdpPort = await freePort();
  const env = { ...process.env, MONEO_DESKTOP_HOME: home, MONEO_DESKTOP_OPEN_EXTERNAL_LOG: path.join(home, "external.log"), MONEO_DESKTOP_DEBUG: "1" };
  const mainLogBefore = parseLog(path.join(home, "logs", "main.log")).length;
  const backendLogBefore = parseLog(path.join(home, "logs", "backend.log")).length;
  const t0 = Date.now();
  const child = spawn(electron, ["desktop", `--remote-debugging-port=${cdpPort}`], { cwd: root, env, stdio: "ignore" });
  let exited = false; child.on("exit", () => { exited = true; });
  const marks = { spawn: 0 };
  const targets = async () => (await (await fetch(`http://127.0.0.1:${cdpPort}/json/list`)).json());
  await until("cdp", targets, 60_000);
  const browser = await chromium.connectOverCDP(`http://127.0.0.1:${cdpPort}`);
  const pages = () => browser.contexts().flatMap(c => c.pages());
  const setup = await until("setup page", async () => pages().find(p => p.url().endsWith("/setup/index.html")), 30_000).catch(() => undefined);
  if (setup) {
    const paint = await setup.evaluate(async () => { for (let i = 0; i < 200; i++) { const e = performance.getEntriesByName("first-contentful-paint")[0]; if (e) return performance.timeOrigin + e.startTime; await new Promise(r => setTimeout(r, 10)); } return 0; }).catch(() => 0);
    if (paint) marks["setup window first paint"] = paint - t0;
  }
  const page = await until("app page", async () => pages().find(p => /^http:\/\/localhost:\d+\//.test(p.url())), 300_000);
  const home1 = await page.evaluate(async () => {
    for (;;) {
      const h = document.querySelector("main h1, h1");
      if (h && h.getBoundingClientRect().height > 0 && document.readyState !== "loading") break;
      await new Promise(r => requestAnimationFrame(r));
    }
    const nav = performance.getEntriesByType("navigation")[0];
    const fcp = performance.getEntriesByName("first-contentful-paint")[0];
    return { origin: performance.timeOrigin, fcp: fcp ? performance.timeOrigin + fcp.startTime : 0, ttfb: nav ? performance.timeOrigin + nav.responseStart : 0, heading: performance.timeOrigin + performance.now(), path: location.pathname };
  });
  await page.waitForLoadState("load").catch(() => {});
  const loaded = await page.evaluate(() => { const nav = performance.getEntriesByType("navigation")[0]; return nav ? performance.timeOrigin + nav.loadEventEnd : 0; });
  marks["Home request sent"] = home1.origin - t0;
  marks["Home first byte"] = home1.ttfb - t0;
  marks["app window first paint"] = home1.fcp - t0;
  marks["Home heading shows"] = home1.heading - t0;
  marks["Home load event"] = loaded - t0;
  await sleep(4000);
  const procs = tree(child.pid, home);
  await browser.close().catch(() => {});
  const mainLog = parseLog(path.join(home, "logs", "main.log")).slice(mainLogBefore);
  const backendLog = parseLog(path.join(home, "logs", "backend.log")).slice(backendLogBefore);
  const events = [...mainLog.map(e => ({ ...e, src: "main" })), ...backendLog.map(e => ({ ...e, src: "backend" }))].sort((a, b) => a.at - b.at).map(e => ({ t: e.at - t0, src: e.src, text: e.text.slice(0, 120) }));
  spawn(electron, ["desktop", "--quit"], { cwd: root, env, stdio: "ignore" });
  await until("exit", async () => exited, 90_000);
  await sleep(1500);
  const ws = procs.reduce((s, p) => s + Number(p.ws), 0), priv = procs.reduce((s, p) => s + p.priv, 0);
  return { label, path: home1.path, marks, events, processes: procs.length, workingSetMB: Math.round(ws / 1048576), privateMB: Math.round(priv / 1048576), procs: procs.map(p => `${p.name} ${Math.round(p.ws / 1048576)}MB`) };
}

const home = mkdtempSync(path.join(os.tmpdir(), "moneo-measure-"));
const results = [];
try {
  results.push(await startOnce(home, "first run"));
  for (let i = 0; i < runs; i++) results.push(await startOnce(home, `start ${i + 1}`));
} finally {
  writeFileSync(out, JSON.stringify(results, null, 2));
  rmSync(home, { recursive: true, force: true, maxRetries: 10, retryDelay: 500 });
}
for (const r of results) {
  console.log(`\n== ${r.label} (${r.path}) procs ${r.processes} ws ${r.workingSetMB} MB priv ${r.privateMB} MB`);
