import { NextResponse } from "next/server";
import { z } from "zod";
import { desktopBridgeUrl } from "@/lib/env";

const bridge = desktopBridgeUrl;
export const isDesktop = () => Boolean(bridge());

const CONTINUE_PAGE = "<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Return to Moneo</title>"
  + "<style>body{font:16px/1.5 system-ui,sans-serif;max-width:32rem;margin:15vh auto;padding:0 1rem;color:#222;background:#fff}@media (prefers-color-scheme:dark){body{color:#eee;background:#0f1011}}</style>"
  + "<body><h1>Continue in Moneo</h1><p>The result is now open in the Moneo app. You can close this browser tab.</p></body></html>";

export async function connectionReturn(base: string | URL, path: string) {
  const url = bridge();
  if (url) {
    const handedToTheApp = await fetch(`${url}/return`, { method: "POST", headers: { "x-moneo-return": path }, signal: AbortSignal.timeout(10_000) }).then(response => response.ok, () => false);
    if (handedToTheApp) return new Response(CONTINUE_PAGE, {
      headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store", "content-security-policy": "default-src 'none'; style-src 'unsafe-inline'; frame-ancestors 'none'" },
    });
  }
  return NextResponse.redirect(new URL(path, base), 303);
}

const updateStatus = z.object({
  current: z.string(),
  state: z.enum(["idle", "checking", "current", "available", "downloading", "installing", "error"]),
  latest: z.string().optional(),
  percent: z.number().optional(),
  error: z.string().optional(),
  installs: z.boolean(),
});
export const hasBankTokenKey = () => Boolean(read("BANK_TOKEN_ENCRYPTION_KEY"));
export const bankTokenKey = () => parse("BANK_TOKEN_ENCRYPTION_KEY", bankTokenKeySchema, read("BANK_TOKEN_ENCRYPTION_KEY"));

export const cronSecret = REDACTED Source = process.env) => read("CRON_SECRET", env);

export function ownerCredentials() {
  const email = read("MONEO_OWNER_EMAIL"), password = read("MONEO_OWNER_PASSWORD");
  return email && password ? { email, password } : null;
}

export const dataDir = () => read("MONEO_DATA_DIR") ?? `${process.cwd()}/.data`;

export const isDesktopRuntime = () => read("MONEO_DESKTOP") === "1";
export const isDesktopPreview = () => isDesktopRuntime() && read("MONEO_DESKTOP_PREVIEW") === "1";
export const desktopBridgeUrl = () => isDesktopRuntime() && read("MONEO_DESKTOP_BRIDGE") ? parse("MONEO_DESKTOP_BRIDGE", urlSchema, read("MONEO_DESKTOP_BRIDGE")) : undefined;

export const enableBankingApiUrl = () => parse("ENABLE_BANKING_API_URL", urlSchema.default(DEFAULT_ENABLE_BANKING_API_URL), read("ENABLE_BANKING_API_URL"));
export const scalableMcpOrigin = () => parse("SCALABLE_MCP_ORIGIN", urlSchema.default(DEFAULT_SCALABLE_MCP_ORIGIN), read("SCALABLE_MCP_ORIGIN"));

export const SERVICE_KEY_VARIABLES = ["OPENAI_API_KEY", "OPENROUTER_API_KEY", "ENABLE_BANKING_APP_ID", "ENABLE_BANKING_PRIVATE_KEY"] as const;
export type ServiceKeyVariable = (typeof SERVICE_KEY_VARIABLES)[number];
