  const rows = JSON.parse(readFileSync(f, "utf8"));
  console.log(`\n## ${f.split(/[\\/]/).pop()}`);
  for (const r of rows) {
    const ev = name => r.events.find(e => e.text.startsWith(name))?.t;
    console.log(`${r.label.padEnd(10)} backend ${ev("Backend ready")} next ${ev("Next server is ready")} heading ${Math.round(r.marks["Home heading shows"])} ttfb ${Math.round(r.marks["Home first byte"] - r.marks["Home request sent"])} procs ${r.processes} ws ${r.workingSetMB} priv ${r.privateMB} conn ${r.detail?.connect ?? "-"} | ${(r.visits ?? []).join(" ")}`);
  }
}
EOF
cd $S && node summary.mjs $(ls pre-*.json)
